WITH valid AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, LENGTH(status) AS status_length FROM orders WHERE channel IS DISTINCT FROM 'mobile'), cleaned AS (SELECT *, INITCAP(TRIM(status)) AS status_title, CASE WHEN shipping_fee >= 32 THEN 'High' WHEN shipping_fee >= 10 THEN 'Medium' ELSE 'Low' END AS shipping_fee_band FROM valid WHERE channel IS NOT NULL), matched_keys AS (SELECT status, channel FROM cleaned INTERSECT ALL SELECT status, channel FROM orders WHERE channel = 'store'), verified AS (SELECT s.* FROM cleaned s INNER JOIN matched_keys k ON s.status = k.status AND s.channel = k.channel), eligible AS (SELECT s.* FROM verified s WHERE NOT EXISTS (SELECT 1 FROM order_items x WHERE x.order_id = s.id AND x.order_id IN (16, 23, 36, 37))) SELECT s.id, s.customer_id, s.status, s.channel, s.amount, s.discount, s.shipping_fee, s.status_length, s.status_title, (SELECT AVG(x.shipping_fee) FROM orders x WHERE x.customer_id = s.customer_id) AS avg_order_shipping_fee FROM eligible s;
